targets.description:
List of monitoring targets to configure in mrtg.cfg. Each target represents a device or metric source.
items: {
  id: { type: string, default: "local_cpu", description: "Unique identifier for the target in the config. Used in Target[ID] directives." },
  name: { type: string, default: "Local CPU Load", description: "Human-readable name for the target." },
  description: { type: string, default: "System CPU utilization", description: "Brief description of what is being monitored." },
  target_expr: { type: string, default: "1.3.6.1.2.1.25.3.3.1.2.1#1.3.6.1.2.1.25.3.3.1.2.1@public:localhost", description: "The SNMP OID or script command expression. Format: OID1#OID2@community:host or script.sh." },
  max_bytes: { type: number, default: 100, description: "Maximum expected value for scaling the Y-axis. Set to 100 for percentage loads, or bytes for traffic." },
  title: { type: string, default: "Local CPU Load", description: "Title displayed on the generated HTML page for this target." },
  max_warn: { type: string, default: "N/A", description: "Optional warning threshold. If current value > this, warning logged. Use 'N/A' or empty string to disable." }
}
